function save(){localStorage.setItem('madar-save',JSON.stringify(state))}
function fmt(num,d=1){return Number(num).toFixed(d)}
function dateString(){const months=['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'];return `الإثنين، ١٢ ${months[state.month%12]} ${state.year}`}
function metricCard(title,value,unit,icon,change,up=true,foot='مقارنة بالشهر السابق'){return `<article class="metric-card"><div class="metric-head"><span>${title}</span><span class="metric-icon">${icon}</span></div><div class="metric-value">${value}<small style="font:500 10px 'IBM Plex Sans Arabic';color:#9aa69c;margin-right:4px">${unit||''}</small></div><div class="metric-foot"><span class="trend ${up?'':'down'}">${up?'↑':'↓'} ${change}</span><i class="separator"></i><span>${foot}</span></div></article>`}
function head(title,subtitle,actions=''){return `<div class="page-head"><div><div class="eyebrow"><i class="line"></i> مركز العمليات الوطنية</div><h1>${title}</h1><div class="page-subtitle">${subtitle}</div></div><div class="head-actions">${actions}</div></div>`}
function panel(title,content,subtitle='',tools=''){return `<section class="panel"><div class="panel-head"><div><div class="panel-title">${title}</div>${subtitle?`<div class="panel-caption">${subtitle}</div>`:''}</div><div class="panel-tools">${tools}</div></div>${content}</section>`}
function mapMarkup(){return `<div class="country-map"><div class="map-glow"></div><svg class="map-svg" viewBox="0 0 500 320" role="img" aria-label="خريطة أقاليم جمهورية النوران">${provinces.map((p,i)=>`<path class="province ${state.selectedRegion===p.name?'selected':''}" data-region="${p.name}" d="${p.path}" fill="${p.fill}"/><text class="province-label" x="${p.label[0]}" y="${p.label[1]}">${p.name}</text>`).join('')}<circle class="map-capital-ring" cx="266" cy="124" r="9"/><circle class="map-capital" cx="266" cy="124" r="3"/></svg><div class="map-tooltip"><strong>${state.selectedRegion} <span style="color:#d9bc7a;font-size:8px">●</span></strong><span>${(provinces.find(p=>p.name===state.selectedRegion)||provinces[0]).pop} نسمة</span></div><div class="map-legend"><i class="legend-dot"></i><span>العاصمة الوطنية</span><span style="margin-right:8px">·</span><span>٦ أقاليم إدارية</span></div><div class="map-scale">0 ━━━━━ 100 km</div></div>`}
function chartMarkup(){return `<div class="chart-wrap"><div class="chart-legend"><span><i class="legend-gdp"></i>الناتج المحلي (مليار)</span><span><i class="legend-inflation"></i>التضخم %</span></div><svg class="chart" viewBox="0 0 510 155" preserveAspectRatio="none" aria-label="الرسم البياني الاقتصادي"><defs><linearGradient id="greenFill" x1="0" x2="0" y1="0" y2="1"><stop offset="0" stop-color="#aacf7f" stop-opacity=".22"/><stop offset="1" stop-color="#aacf7f" stop-opacity="0"/></linearGradient></defs>${[25,58,91,124].map(y=>`<line class="grid-line" x1="34" y1="${y}" x2="500" y2="${y}"/>`).join('')}<text x="3" y="27">300</text><text x="3" y="60">280</text><text x="3" y="93">260</text><text x="3" y="126">240</text><path class="area-gdp" d="M40 107 110 95 180 99 250 76 320 84 390 52 465 39 465 128 40 128Z"/><path class="line-gdp" d="M40 107 110 95 180 99 250 76 320 84 390 52 465 39"/><path class="line-inf" d="M40 76 110 79 180 68 250 73 320 61 390 67 465 55"/>${[[40,107],[110,95],[180,99],[250,76],[320,84],[390,52],[465,39]].map(([x,y])=>`<circle cx="${x}" cy="${y}" r="3.5"/>`).join('')}${[[40,76],[110,79],[180,68],[250,73],[320,61],[390,67],[465,55]].map(([x,y])=>`<circle class="dot-inf" cx="${x}" cy="${y}" r="2.5"/>`).join('')}<text x="34" y="149">نوفمبر</text><text x="105" y="149">ديسمبر</text><text x="177" y="149">يناير</text><text x="249" y="149">فبراير</text><text x="320" y="149">مارس</text><text x="391" y="149">أبريل</text><text x="465" y="149">مايو</text></svg></div>`}
function eventList(){return `<div class="news-list">${state.events.slice(0,4).map(e=>`<div class="news-item"><span class="news-icon">${e.icon}</span><div class="news-copy"><b>${e.title}</b><small>${e.time}</small></div><span class="news-status ${e.warn?'warn':''}">${e.status}</span></div>`).join('')}</div>`}
function overview(){return `${head('صباح الخير، سيادة الرئيس','إليك موجز حالة الدولة لهذا اليوم. مؤشرات النوران مستقرة مع فرص نمو واعدة.','<button class="outline-btn" id="reportBtn"><span>▤</span> التقرير اليومي</button>')}<div class="metrics-grid">${metricCard('الناتج المحلي الإجمالي',fmt(state.gdp),'مليار $','◈',`${fmt(state.growth)}%`,true)}${metricCard('معدل التضخم',`${fmt(state.inflation)}%`,'','↗','0.3%',false)}${metricCard('رضا المواطنين',`${state.approval}%`,'','♡','2.1%',true)}${metricCard('الدين العام',`${fmt(state.debt)}%`,'من الناتج','▤','0.8%',false,'من الناتج المحلي')}</div><div class="layout-main"><div class="column">${panel('خريطة جمهورية النوران',mapMarkup(),'عرض جغرافي لمراكز السكان والموارد','<select class="select-mini" id="mapFilter"><option>الكثافة السكانية</option><option>البنية التحتية</option><option>مؤشر الخدمات</option></select><button class="panel-link" data-view="regions">تفاصيل الأقاليم ←</button>')}<div class="lower-grid">${panel('المؤشرات الاقتصادية','<div class="chart-wrap-placeholder"></div>'+chartMarkup(),'أداء الاقتصاد خلال آخر ٧ أشهر','<select class="select-mini"><option>آخر ٧ أشهر</option><option>آخر سنة</option></select>')}${panel('قرارات وموجز الأخبار',eventList(),'آخر المستجدات من الوزارات','<button class="panel-link" data-view="laws">عرض الكل ←</button>')}</div></div><div class="column">${panel('أولويات اليوم','<div class="side-stats"><div class="stat-row"><span>أمن الطاقة</span><div class="bar-mini"><i style="width:'+state.energy+'%"></i></div><b>'+state.energy+'%</b></div><div class="stat-row"><span>الأمن المائي</span><div class="bar-mini gold"><i style="width:'+state.water+'%"></i></div><b>'+state.water+'%</b></div><div class="stat-row"><span>الاستقرار العام</span><div class="bar-mini"><i style="width:'+state.security+'%"></i></div><b>'+state.security+'%</b></div><div class="stat-row"><span>البطالة</span><div class="bar-mini gold"><i style="width:'+(100-state.unemployment*5)+'%"></i></div><b>'+fmt(state.unemployment)+'%</b></div></div>','مؤشرات الأمن والخدمات الوطنية')}${panel('قرارات سريعة','<div class="quick-actions"><button class="quick-action" data-action="schools"><span class="qa-icon">♧</span>دعم المدارس</button><button class="quick-action" data-action="water"><span class="qa-icon">⌁</span>خطة المياه</button><button class="quick-action" data-action="trade"><span class="qa-icon">↗</span>تحفيز التجارة</button></div>','إجراءات ذات أثر وطني')}${panel('النبض الوطني','<div class="side-stats"><div class="stat-row"><span>النمو الاقتصادي</span><b class="positive">+'+fmt(state.growth)+'%</b></div><div class="stat-row"><span>الاحتياطي النقدي</span><b>'+fmt(state.reserves)+' مليار $</b></div><div class="stat-row"><span>عدد السكان</span><b>'+fmt(state.population)+' مليون</b></div></div>','ملخص المؤشرات الرئيسية')}</div></div>`}
function rangeRow(label,key,min,max,unit,description){return `<div class="control-row"><div class="control-top"><div><b>${label}</b><small> · ${description}</small></div><span><output>${state[key]}</output>${unit}</span></div><input type="range" min="${min}" max="${max}" value="${state[key]}" data-key="${key}"/><div class="range-labels"><span>منخفض</span><span>متوازن</span><span>مرتفع</span></div></div>`}
function economy(){return `${head('إدارة الاقتصاد والمالية','وازن بين النمو المستدام، الإيرادات العامة، وجودة الخدمات للمواطنين.','<button class="soft-btn" data-action="budget"><span class="tiny">＋</span> إعداد الموازنة</button>')}<div class="metrics-grid">${metricCard('الناتج المحلي',fmt(state.gdp),'مليار $','◈',fmt(state.growth)+'%',true)}${metricCard('الإيرادات الحكومية',fmt(64.8+state.tax*.24),'مليار $','↗','4.2%',true)}${metricCard('الدين العام',fmt(state.debt),'% من الناتج','▤','0.8%',false)}${metricCard('احتياطي النقد الأجنبي',fmt(state.reserves),'مليار $','◉','1.4%',true)}</div><div class="section-grid"><div class="column">${panel('أدوات السياسة المالية',`<div class="control-list">${rangeRow('معدل ضريبة الدخل','tax',5,40,'%','ضريبة تصاعدية على الأفراد والشركات')}${rangeRow('الإنفاق على الصحة','health',5,30,'%','من إجمالي الموازنة السنوية')}${rangeRow('الإنفاق على التعليم','education',5,30,'%','من إجمالي الموازنة السنوية')}${rangeRow('الاستثمار في البنية التحتية','infra',3,25,'%','نقل وطاقة ومياه واتصالات')}</div>`,'تُحسب آثار السياسة تدريجيًا مع نهاية كل شهر')}${panel('حسابات الدولة','<div class="side-stats"><div class="stat-row"><span>الإيرادات السنوية المتوقعة</span><b>64.8 مليار $</b></div><div class="stat-row"><span>المصروفات السنوية المقدّرة</span><b>71.2 مليار $</b></div><div class="stat-row"><span>العجز المالي</span><b class="negative">−6.4 مليار $</b></div><div class="stat-row"><span>خدمة الدين / الإيرادات</span><b>18.6%</b></div></div>','بيانات الموازنة العامة · ٢٠٢٥')}</div><div class="column">${panel('مؤشر أداء الاقتصاد',chartMarkup(),'اتجاه الناتج المحلي والتضخم')}${panel('مذكرة المستشار الاقتصادي','<div class="decision-card"><h3>مساحة لتحفيز النمو</h3><p>تشير التوقعات إلى إمكانية تعزيز النمو عبر توجيه استثمارات إضافية نحو النقل والتعليم، مع مراقبة أثر التوسع المالي على الدين والتضخم.</p><button class="soft-btn" data-action="memo">قراءة التوصيات الكاملة <span>←</span></button></div>','تحليل مكتب السياسات · قبل ساعة')}${panel('أدوات الإدارة','<div class="quick-actions"><button class="quick-action" data-action="tax"><span class="qa-icon">％</span>ضرائب ورسوم</button><button class="quick-action" data-action="budget"><span class="qa-icon">▤</span>الموازنة</button><button class="quick-action" data-action="trade"><span class="qa-icon">↗</span>التجارة</button></div>')}</div></div>`}

