 class="quick-actions"><button class="quick-action" data-action="tax"><span class="qa-icon">％</span>ضرائب ورسوم</button><button class="quick-action" data-action="budget"><span class="qa-icon">▤</span>الموازنة</button><button class="quick-action" data-action="trade"><span class="qa-icon">↗</span>التجارة</button></div>')}</div></div>`}
function society(){return `${head('المجتمع والخدمات','تابع جودة الحياة، الخدمات الأساسية، والتركيبة السكانية في كل أنحاء البلاد.')}<div class="metrics-grid">${metricCard('عدد السكان',fmt(state.population),'مليون نسمة','♧','1.7%',true)}${metricCard('معدل البطالة',fmt(state.unemployment)+'%','','⌁','0.2%',false)}${metricCard('التغطية الصحية','91%','','＋','1.3%',true)}${metricCard('الالتحاق بالتعليم','94%','','▤','0.8%',true)}</div><div class="section-grid"><div class="column">${panel('مؤشرات جودة الحياة','<div class="side-stats">'+[['الوصول إلى مياه نظيفة',state.water],['التغطية الصحية',91],['الالتحاق بالمدارس',94],['الوصول إلى الإنترنت',83],['رضا المواطنين',state.approval]].map(([l,v])=>`<div class="stat-row"><span>${l}</span><div class="bar-mini"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('')+'</div>','مقارنة الأهداف الوطنية بالوضع الراهن')}${panel('الإنفاق الاجتماعي',`<div class="control-list">${rangeRow('ميزانية الصحة','health',5,30,'%','من الموازنة العامة')}${rangeRow('ميزانية التعليم','education',5,30,'%','من الموازنة العامة')}</div>`,'ضبط الإنفاق يظهر أثره في دورة الميزانية المقبلة')}</div><div class="column">${panel('التركيبة السكانية','<div class="decision-card"><h3>مجتمع شاب ونشط</h3><p>متوسط العمر ٢٧.٤ سنة، ويشكّل السكان في سن العمل ٦٤٪ من إجمالي السكان. سياسات التدريب وفرص العمل المبكر قد تعزز الإنتاجية.</p><div class="side-stats"><div class="stat-row"><span>دون ١٥ عامًا</span><b>٢٨٪</b></div><div class="stat-row"><span>سن العمل</span><b>٦٤٪</b></div><div class="stat-row"><span>فوق ٦٥ عامًا</span><b>٨٪</b></div></div></div>','تقديرات المركز الوطني للإحصاء')}${panel('البرامج الاجتماعية','<div class="quick-actions"><button class="quick-action" data-action="schools"><span class="qa-icon">♧</span>دعم المدارس</button><button class="quick-action" data-action="health"><span class="qa-icon">＋</span>رعاية صحية</button><button class="quick-action" data-action="jobs"><span class="qa-icon">↗</span>فرص العمل</button></div>')}</div></div>`}
function regions(){return `${head('الأقاليم والمحافظات','ستة أقاليم إدارية، لكل منها مواردها واحتياجاتها وأولوياتها المحلية.')}<div class="section-grid"><div class="column">${panel('الخريطة الإدارية',mapMarkup(),'اختر إقليمًا لعرض ملفه ومؤشراته','<button class="panel-link" data-action="distribute">توزيع الموارد ←</button>')}${panel('ملفات الأقاليم',`<div class="province-list">${provinces.map(p=>`<button class="province-card ${state.selectedRegion===p.name?'selected':''}" data-region="${p.name}"><b>${p.name}</b><small>${p.pop} نسمة</small><strong>${p.health}%</strong><span class="health">مؤشر الخدمات</span></button>`).join('')}</div>`,'مؤشر جودة الخدمات من ١٠٠')}</div><div class="column">${panel(`ملف إقليم ${state.selectedRegion}`,`<div class="decision-card"><h3>ملخص الاحتياجات المحلية</h3><p>${state.selectedRegion} يضم ${(provinces.find(p=>p.name===state.selectedRegion)||provinces[0]).pop} نسمة، ومؤشر جودة الخدمات ${(provinces.find(p=>p.name===state.selectedRegion)||provinces[0]).health} من ١٠٠. تتولى الإدارة الإقليمية تنسيق الخدمات البلدية والصحة والتعليم والتنمية الاقتصادية.</p><div class="side-stats"><div class="stat-row"><span>مؤشر الخدمات</span><b>${(provinces.find(p=>p.name===state.selectedRegion)||provinces[0]).health}/100</b></div><div class="stat-row"><span>الأولوية التنموية</span><b>${state.selectedRegion==='الساحل'?'الموانئ والتجارة':state.selectedRegion==='الواحة'?'المياه والزراعة':'الصحة والنقل'}</b></div></div><button class="soft-btn" data-action="regional">اعتماد مبادرة للإقليم</button></div>`,'الإدارة المحلية · تحديث هذا الأسبوع')}${panel('توزيع الاستثمار','<div class="side-stats"><div class="stat-row"><span>النقل والطرق</span><b>٢٨٪</b></div><div class="stat-row"><span>الصحة والتعليم</span><b>٣٢٪</b></div><div class="stat-row"><span>المياه والطاقة</span><b>٢٤٪</b></div><div class="stat-row"><span>تنمية اقتصادية</span><b>١٦٪</b></div></div>','حصة من المشاريع الجارية')}</div></div>`}
function security(){return `${head('الأمن والدفاع','حماية السكان والبنية التحتية مع تعزيز الجاهزية المدنية وإدارة المخاطر.')}<div class="metrics-grid">${metricCard('الاستقرار الوطني',state.security+'/100','','⬡','1.2%',true)}${metricCard('جاهزية الطوارئ','78%','','⌑','3%',true)}${metricCard('الأمن الغذائي','84%','','▦','0.4%',true)}${metricCard('أمن الطاقة',state.energy+'%','','ϟ','2.1%',true)}</div><div class="section-grid"><div class="column">${panel('أولويات الأمن الوطني','<div class="side-stats">'+[['استقرار الحدود',76],['سلامة البنية التحتية',88],['جاهزية الدفاع المدني',78],['الأمن السيبراني',81],['الأمن الغذائي',84]].map(([l,v])=>`<div class="stat-row"><span>${l}</span><div class="bar-mini"><i style="width:${v}%"></i></div><b>${v}%</b></div>`).join('')+'</div>','تقييم المركز الوطني لإدارة الأزمات')}${panel('تخصيص الإنفاق الدفاعي',`<div class="control-list">${rangeRow('حصة الدفاع من الموازنة','defense',5,25,'%','تشمل الجاهزية والدفاع المدني')}${rangeRow('البنية التحتية','infra',3,25,'%','استثمار مزدوج للاستخدام المدني والطوارئ')}</div>`,'وازن بين الجاهزية والأولويات الاجتماعية')}</div><div class="column">${panel('مركز إدارة المخاطر','<div class="news-list"><div class="news-item"><span class="news-icon">⌁</span><div class="news-copy"><b>انخفاض مخزون المياه في إقليم الواحة</b><small>خطر متوسط · الموارد المائية</small></div><span class="news-status warn">مراقبة</span></div><div class="news-item"><span class="news-icon">ϟ</span><div class="news-copy"><b>احتياطي الطاقة ضمن المستوى الآمن</b><small>تحديث قبل ٢ ساعة · الطاقة</small></div><span class="news-status">مستقر</span></div><div class="news-item"><span class="news-icon">⬡</span><div class="news-copy"><b>تمرين إخلاء مدني في العاصمة</b><small>الخميس القادم · الدفاع المدني</small></div><span class="news-status">مجدول</span></div></div>','تنبيهات القطاعات الحيوية')}${panel('إجراء وقائي','<div class="decision-card"><h3>تعزيز الأمن المائي</h3><p>يمكن إطلاق برنامج وطني لتقليل الفاقد من شبكات المياه، وربط بيانات المخزون بمراكز الإنذار المبكر.</p><button class="soft-btn" data-action="water">إطلاق خطة ترشيد المياه</button></div>')}</div></div>`}

