 function foreign(){return `${head('العلاقات الدولية','إدارة الشراكات التجارية والدبلوماسية ومتابعة المصالح الوطنية في الخارج.')}<div class="metrics-grid">${metricCard('الشراكات النشطة','24','','◎','2 اتفاقية',true)}${metricCard('حجم التبادل التجاري','38.6','مليار $','↗','6.4%',true)}${metricCard('الصادرات غير النفطية','12.3','مليار $','◈','8.1%',true)}${metricCard('التدفقات الاستثمارية','4.8','مليار $','＋','3.2%',true)}</div><div class="section-grid"><div class="column">${panel('الشركاء الاستراتيجيون','<div class="table-wrap"><table class="data-table"><thead><tr><th>الشريك</th><th>نوع العلاقة</th><th>التبادل التجاري</th><th>الحالة</th></tr></thead><tbody><tr><td>اتحاد السواحل</td><td>تجارة وطاقة</td><td>8.4 مليار $</td><td><span class="badge">شراكة قوية</span></td></tr><tr><td>جمهورية أرفان</td><td>تقنية وتعليم</td><td>5.2 مليار $</td><td><span class="badge blue">اتفاق تعاون</span></td></tr><tr><td>مملكة دال</td><td>استثمار وبنية تحتية</td><td>4.7 مليار $</td><td><span class="badge">مفاوضات</span></td></tr><tr><td>رابطة الجنوب</td><td>زراعة وأمن غذائي</td><td>2.9 مليار $</td><td><span class="badge warn">قيد المراجعة</span></td></tr></tbody></table></div>`,'بيانات التجارة الثنائية · الربع الأول ٢٠٢٥')}${panel('أجندة دبلوماسية','<div class="news-list"><div class="news-item"><span class="news-icon">◎</span><div class="news-copy"><b>قمة التنمية الإقليمية</b><small>العاصمة · ١٨ مايو</small></div><span class="news-status">مجدول</span></div><div class="news-item"><span class="news-icon">↗</span><div class="news-copy"><b>وفد تجاري من اتحاد السواحل</b><small>وزارة الخارجية · ٢١ مايو</small></div><span class="news-status">مؤكد</span></div><div class="news-item"><span class="news-icon">▤</span><div class="news-copy"><b>مراجعة اتفاقية التجارة الحرة</b><small>مكتب المستشارين · ٢٥ مايو</small></div><span class="news-status warn">تحضير</span></div></div>')}</div><div class="column">${panel('أولويات السياسة الخارجية','<div class="decision-card"><h3>دبلوماسية اقتصادية نشطة</h3><p>توسيع منافذ تصدير المنتجات الوطنية، جذب استثمارات التقنية النظيفة، وتعزيز التعاون العلمي الإقليمي.</p><button class="soft-btn" data-action="trade">إطلاق بعثة ترويج تجاري</button></div>','توصيات مجلس الأمن الاقتصادي')}${panel('مواقف الدولة','<div class="side-stats"><div class="stat-row"><span>التعاون الإقليمي</span><b>أولوية</b></div><div class="stat-row"><span>الأمن الغذائي</span><b>شراكات استراتيجية</b></div><div class="stat-row"><span>المناخ والطاقة النظيفة</span><b>التزام وطني</b></div><div class="stat-row"><span>التبادل الأكاديمي</span><b>توسع مستمر</b></div></div>','المبادئ التوجيهية لسياسة النوران')}</div></div>`}
 function projects(){const items=[['توسعة ميناء السهل','البنية التحتية · الساحل',72,'▤'],['شبكة المياه الوطنية','موارد · ٤ أقاليم',48,'⌁'],['مدينة النور للطاقة الشمسية','طاقة نظيفة · الواحة',31,'ϟ'],['المدارس الرقمية','تعليم · وطني',64,'♧'],['طريق المرتفعات السريع','نقل · المرتفعات',86,'↗'],['المركز الطبي الإقليمي','صحة · الجنوب',22,'＋']];return `${head('المشاريع الوطنية','تابع تنفيذ البنية التحتية والبرامج التنموية وأثرها المتوقع على حياة الناس.','<button class="soft-btn" data-action="newProject"><span class="tiny">＋</span> مشروع جديد</button>')}<div class="metrics-grid">${metricCard('مشاريع قيد التنفيذ','18','','▦','3 جديدة',true)}${metricCard('الإنفاق الرأسمالي','8.4','مليار $','◈','في الخطة السنوية',true)}${metricCard('معدل الإنجاز','57%','','↗','4.3%',true)}${metricCard('مشاريع على المسار','14','','✓','من أصل 18',true)}</div>${panel('محفظة المشاريع الجارية',`<div class="province-list" style="grid-template-columns:repeat(2,1fr)">${items.map(([t,d,p,i])=>`<div class="project-card" style="border:1px solid #303b33;border-radius:8px;background:#1a241d"><div class="project-symbol">${i}</div><div class="project-details"><b>${t}</b><p>${d}</p><div class="project-progress"><i style="width:${p}%"></i></div></div><span class="project-percent">${p}%</span></div>`).join('')}</div>`,'تحديثات الوزارات · مايو ٢٠٢٥','<select class="select-mini"><option>كل القطاعات</option><option>البنية التحتية</option></select>')}`}
 function laws(){const rows=[['حزمة دعم المشاريع الصغيرة','اقتصاد','مقترح','مراجعة مجلس الوزراء'],['قانون كفاءة المياه','موارد','قيد النقاش','لجنة البيئة'],['تحديث معايير التعليم الأساسي','تعليم','معتمد','وزارة التعليم'],['برنامج تمويل الرعاية الأولية','صحة','قيد التنفيذ','وزارة الصحة'],['اتفاقية تسهيل التجارة الإقليمية','خارجية','مقترح','لجنة الشؤون الخارجية'],['لائحة الطاقة المتجددة','طاقة','معتمد','وزارة الطاقة']];return `${head('التشريعات والقرارات','مسار السياسات من المقترح إلى الدراسة، الاعتماد، ثم التنفيذ.','<button class="soft-btn" data-action="newLaw"><span class="tiny">＋</span> مقترح سياسة</button>')}<div class="metrics-grid">${metricCard('قرارات منفذة','34','','✓','هذا العام',true)}${metricCard('قيد الدراسة','8','','≡','4 لجان',true)}${metricCard('مشروعات قوانين','5','','▤','مقترحة',true)}${metricCard('معدل الإنجاز','82%','','↗','للمستهدفات',true)}</div>${panel('سجل السياسات والقرارات',`<div class="table-wrap"><table class="data-table"><thead><tr><th>الموضوع</th><th>القطاع</th><th>المرحلة</th><th>الجهة المسؤولة</th><th>إجراء</th></tr></thead><tbody>${rows.map(([t,s,st,agency])=>`<tr><td>${t}</td><td>${s}</td><td><span class="badge ${st==='قيد النقاش'?'warn':st==='قيد التنفيذ'?'blue':''}">${st}</span></td><td>${agency}</td><td><button class="panel-link" data-action="policy">التفاصيل ←</button></td></tr>`).join('')}</tbody></table></div><div class="empty-foot">آخر مزامنة للسجل: قبل ١٨ دقيقة · جميع الأوقات بالتوقيت المحلي</div>`,'شفافية القرار ومتابعة التنفيذ','<select class="select-mini"><option>كل المراحل</option><option>مقترح</option><option>معتمد</option></select>')}`}
+function render(){const root=document.getElementById('viewRoot');root.innerHTML=({overview,economy,society,regions,security,foreign,projects,laws})[currentView]();document.getElementById('pageCrumb').textContent=viewNames[currentView];document.getElementById('dateLabel').textContent=dateString();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));root.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));root.querySelectorAll('[data-region]').forEach(b=>b.addEventListener('click',()=>{state.selectedRegion=b.dataset.region;save();render()}));root.querySelectorAll('input[type=range]').forEach(input=>input.addEventListener('input',()=>{state[input.dataset.key]=Number(input.value);input.closest('.control-row').querySelector('output').textContent=input.value;const pct=(input.value-input.min)/(input.max-input.min)*100;input.style.background=`linear-gradient(to left,#a8cc80 0 ${pct}%,#354138 ${pct}%)`;save()}));root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>runAction(b.dataset.action)));root.querySelectorAll('#reportBtn').forEach(b=>b.addEventListener('click',showReport));root.querySelectorAll('#mapFilter').forEach(s=>s.addEventListener('change',()=>{const colors={الكثافة:'#6d8753','البنية التحتية':'#4c7978','مؤشر الخدمات':'#927a4a'};root.querySelectorAll('.province').forEach((p,i)=>p.setAttribute('fill',colors[s.value]||provinces[i].fill));toast(`تم تحديث الخريطة: ${s.value}`)}));}
