+function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
+function modal(title,content,button='حسنًا'){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><b>${title}</b><button class="modal-close" aria-label="إغلاق">×</button></div><div class="modal-content">${content}</div><div class="modal-actions"><button class="advance-btn modal-ok">${button}</button><button class="outline-btn modal-close">إغلاق</button></div></div></div>`;root.querySelectorAll('.modal-close,.modal-ok,.modal-backdrop').forEach(el=>el.addEventListener('click',e=>{if(e.target===el||el.classList.contains('modal-close')||el.classList.contains('modal-ok'))root.innerHTML=''}));}
