+const actions={schools:{title:'دعم المدارس',desc:'حزمة دعم للمدارس في الأقاليم الأقل تغطية، تشمل صيانة الفصول وتدريب المعلمين وتوسيع الوجبات المدرسية.',impact:'ميزانية التعليم +1 نقطة · رضا المواطنين +2 · تبدأ الآثار الشهر المقبل',apply:()=>{state.education=Math.min(30,state.education+1);state.approval=Math.min(99,state.approval+2)}},water:{title:'خطة الأمن المائي',desc:'إطلاق برنامج خفض فاقد الشبكات وإصلاح التسربات، مع مراقبة يومية للمخزون في الأقاليم الأكثر جفافًا.',impact:'الأمن المائي +8 نقاط · احتياطي النقد −0.4 مليار دولار · تحسن تدريجي',apply:()=>{state.water=Math.min(100,state.water+8);state.reserves=Math.max(0,state.reserves-.4)}},trade:{title:'بعثة التجارة والاستثمار',desc:'تنظيم بعثة ترويج تجاري لتوسيع أسواق الصادرات الوطنية وجذب استثمارات نوعية في الصناعة النظيفة.',impact:'النمو المتوقع +0.4 نقطة · احتياطي النقد +0.3 مليار دولار',apply:()=>{state.growth+=.4;state.reserves+=.3}},health:{title:'تعزيز الرعاية الصحية',desc:'تمويل مراكز الرعاية الأولية وتوفير وحدات عيادات متنقلة للمناطق الطرفية.',impact:'الإنفاق الصحي +1 نقطة · رضا المواطنين +2',apply:()=>{state.health=Math.min(30,state.health+1);state.approval=Math.min(99,state.approval+2)}},jobs:{title:'برنامج فرص العمل',desc:'حوافز مؤقتة لتوظيف الخريجين وتدريبهم بالشراكة مع الشركات الصغيرة والمتوسطة.',impact:'البطالة −0.4 نقطة · احتياطي النقد −0.2 مليار دولار',apply:()=>{state.unemployment=Math.max(1,state.unemployment-.4);state.reserves=Math.max(0,state.reserves-.2)}},budget:{title:'إعداد الموازنة العامة',desc:'راجع أولويات الإنفاق ومصادر الدخل قبل اعتماد تقديرات الموازنة للعام القادم. كل نقطة إنفاق تعني مفاضلة مع بند آخر.',impact:`حاليًا: الصحة ${state.health}% · التعليم ${state.education}% · الدفاع ${state.defense}% من الموازنة. غيّر القيم عبر أدوات السياسة المالية.`,apply:null},memo:{title:'توصيات المستشار الاقتصادي',desc:'١) توجيه الاستثمار العام إلى النقل واللوجستيات لدعم تنويع الصادرات. ٢) حماية الإنفاق الاجتماعي من التقلبات قصيرة الأجل. ٣) تحسين كفاءة التحصيل بدل رفع الضرائب العامة. ٤) نشر تقرير م