+function advanceMonth(){state.month++;if(state.month>=12){state.month=0;state.year++}const taxEffect=(state.tax-22)*-.018;const investment=(state.infra-12)*.025;const education=(state.education-16)*.008;state.growth=Math.max(-2,Math.min(10,state.growth+.10+investment+education+taxEffect+(Math.random()-.45)*.24));state.gdp*=1+state.growth/1200;state.inflation=Math.max(1,Math.min(20,state.inflation+(state.tax<15?.15:-.04)+(Math.random()-.55)*.32));state.debt=Math.max(15,Math.min(95,state.debt+(state.tax<18?.35:-.10)+(state.infra>17?.12:0)));state.approval=Math.max(20,Math.min(96,Math.round(state.approval+(state.growth>3?1:0)+(state.inflation>6?-1:0)+(Math.random()>.7?1:0))));state.unemployment=Math.max(2,Math.min(25,state.unemployment-.06+(state.growth<2?.1:0)));state.reserves=Math.max(2,state.reserves+(Math.random()-.45)*.5+(state.growth>3?.12:0));state.water=Math.max(25,Math.min(100,state.water+(state.month===7?-5:state.month===1?4:-1)));state.energy=Math.max(40,Math.min(100,state.energy+(Math.random()-.48)*2));let event;if(state.water<55){event={icon:'⌁',title:'تراجع مخزون المياه يتطلب استجابة حكومية',time:'هذا الشهر · وزارة الموارد',status:'أولوية',warn:true};state.approval=Math.max(20,state.approval-1)}else if(state.growth>4.5){event={icon:'↗',title:'تحسن مؤشرات النمو يعزز ثقة المستثمرين',time:'هذا الشهر · وزارة الاقتصاد',status:'إيجابي'}}else{event={icon:'▤',title:'نشر التقرير الشهري لأداء الوزارات',time:'هذا الشهر · مكتب الرئاسة',status:'متابعة'}}state.events.unshift(event);state.events=state.events.slice(0,6);state.history.unshift({month:state.month,year:state.year,gdp:state.gdp,growth:state.growth});state.history=state.history.slice(0,12);save();render();modal(`موجز شهر ${['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'][state.month]} ${state.year}`,`<strong>الاقتصاد:</strong> النمو ${fmt(state.growth)}%، التضخم ${fmt(state.inflation)}%.<br><strong>المواطنون:</strong> الرضا ${state.approval}%، البطالة ${fmt(state.unemployment)}%.<br><strong>المالية:</strong> الدين العام ${fmt(state.debt)}% من الناتج، الاحتياطي ${fmt(state.reserves)} مليار دولار.<br><br><strong>حدث الشهر:</strong> ${event.title}`,'متابعة')}
+document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.getElementById('advanceBtn').addEventListener('click',advanceMonth);document.getElementById('notificationBtn').addEventListener('click',()=>{navigate('overview');showToast('لا توجد تنبيهات عاجلة جديدة.')});document.getElementById('cabinetBtn').addEventListener('click',()=>modal('محضر مجلس الوزراء · الجلسة الدورية','<strong>جدول الأعمال</strong><br>١. مراجعة مؤشرات الأداء الاقتصادي والمالي.<br>٢. خطة استقرار المياه في الأقاليم الداخلية.<br>٣. تسريع المشاريع الوطنية المتأخرة.<br>٤. متابعة جودة الخدمات الصحية والتعليمية.','تم الاطلاع'));render();

