function render(){const root=document.getElementById('viewRoot');root.innerHTML=({overview,economy,society,regions,security,foreign,projects,laws})[currentView]();document.getElementById('pageCrumb').textContent=viewNames[currentView];document.getElementById('dateLabel').textContent=dateString();document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));root.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));root.querySelectorAll('[data-region]').forEach(b=>b.addEventListener('click',()=>{state.selectedRegion=b.dataset.region;save();render()}));root.querySelectorAll('input[type=range]').forEach(input=>input.addEventListener('input',()=>{state[input.dataset.key]=Number(input.value);input.closest('.control-row').querySelector('output').textContent=input.value;const pct=(input.value-input.min)/(input.max-input.min)*100;input.style.background=`linear-gradient(to left,#a8cc80 0 ${pct}%,#354138 ${pct}%)`;save()}));root.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>runAction(b.dataset.action)));root.querySelectorAll('#reportBtn').forEach(b=>b.addEventListener('click',showReport));root.querySelectorAll('#mapFilter').forEach(s=>s.addEventListener('change',()=>{const colors={الكثافة:'#6d8753','البنية التحتية':'#4c7978','مؤشر الخدمات':'#927a4a'};root.querySelectorAll('.province').forEach((p,i)=>p.setAttribute('fill',colors[s.value]||provinces[i].fill));toast(`تم تحديث الخريطة: ${s.value}`)}));}
function navigate(view){if(!viewNames[view])return;currentView=view;render();window.scrollTo({top:0,behavior:'smooth'})}
function showToast(message){const t=document.getElementById('toast');t.textContent=message;t.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>t.classList.remove('show'),2600)}
function modal(title,content,button='حسنًا'){const root=document.getElementById('modalRoot');root.innerHTML=`<div class="modal-backdrop"><div class="modal" role="dialog" aria-modal="true"><div class="modal-head"><b>${title}</b><button class="modal-close" aria-label="إغلاق">×</button></div><div class="modal-content">${content}</div><div class="modal-actions"><button class="advance-btn modal-ok">${button}</button><button class="outline-btn modal-close">إغلاق</button></div></div></div>`;root.querySelectorAll('.modal-close,.modal-ok,.modal-backdrop').forEach(el=>el.addEventListener('click',e=>{if(e.target===el||el.classList.contains('modal-close')||el.classList.contains('modal-ok'))root.innerHTML=''}));}
function showReport(){modal('التقرير اليومي · '+dateString(),`<strong>ملخص تنفيذي</strong><br>تواصل جمهورية النوران مسار نمو معتدل مع استقرار الأسعار وارتفاع رضا المواطنين. الناتج المحلي ${fmt(state.gdp)} مليار دولار، والنمو السنوي ${fmt(state.growth)}%.<br><br><strong>ما يستدعي المتابعة</strong><br>مخزون المياه في إقليم الواحة دون المستهدف. يُوصى بتسريع صيانة الشبكات واعتماد خطة إدارة الطلب.<br><br><strong>أولوية الأسبوع</strong><br>تحفيز الصادرات غير النفطية، ومراجعة مسار المشاريع ذات الإنجاز الأقل من ٤٠٪.`,'تم الاطلاع')}
const actions={schools:{title:'دعم المدارس',desc:'حزمة دعم للمدارس في الأقاليم الأقل تغطية، تشمل صيانة الفصول وتدريب المعلمين وتوسيع الوجبات المدرسية.',impact:'ميزانية التعليم +1 نقطة · رضا المواطنين +2 · تبدأ الآثار الشهر المقبل',apply:()=>{state.education=Math.min(30,state.education+1);state.approval=Math.min(99,state.approval+2)}},water:{title:'خطة الأمن المائي',desc:'إطلاق برنامج خفض فاقد الشبكات وإصلاح التسربات، مع مراقبة يومية للمخزون في الأقاليم الأكثر جفافًا.',impact:'الأمن المائي +8 نقاط · احتياطي النقد −0.4 مليار دولار · تحسن تدريجي',apply:()=>{state.water=Math.min(100,state.water+8);state.reserves=Math.max(0,state.reserves-.4)}},trade:{title:'بعثة التجارة والاستثمار',desc:'تنظيم بعثة ترويج تجاري لتوسيع أسواق الصادرات الوطنية وجذب استثمارات نوعية في الصناعة النظيفة.',impact:'النمو المتوقع +0.4 نقطة · احتياطي النقد +0.3 مليار دولار',apply:()=>{state.growth+=.4;state.reserves+=.3}},health:{title:'تعزيز الرعاية الصحية',desc:'تمويل مراكز الرعاية الأولية وتوفير وحدات عيادات متنقلة للمناطق الطرفية.',impact:'الإنفاق الصحي +1 نقطة · رضا المواطنين +2',apply:()=>{state.health=Math.min(30,state.health+1);state.approval=Math.min(99,state.approval+2)}},jobs:{title:'برنامج فرص العمل',desc:'حوافز مؤقتة لتوظيف الخريجين وتدريبهم بالشراكة مع الشركات الصغيرة والمتوسطة.',impact:'البطالة −0.4 نقطة · احتياطي النقد −0.2 مليار دولار',apply:()=>{state.unemployment=Math.max(1,state.unemployment-.4);state.reserves=Math.max(0,state.reserves-.2)}},budget:{title:'إعداد الموازنة العامة',desc:'راجع أولويات الإنفاق ومصادر الدخل قبل اعتماد تقديرات الموازنة للعام القادم. كل نقطة إنفاق تعني مفاضلة مع بند آخر.',impact:`حاليًا: الصحة ${state.health}% · التعليم ${state.education}% · الدفاع ${state.defense}% من الموازنة. غيّر القيم عبر أدوات السياسة المالية.`,apply:null},memo:{title:'توصيات المستشار الاقتصادي',desc:'١) توجيه الاستثمار العام إلى النقل واللوجستيات لدعم تنويع الصادرات. ٢) حماية الإنفاق الاجتماعي من التقلبات قصيرة الأجل. ٣) تحسين كفاءة التحصيل بدل رفع الضرائب العامة. ٤) نشر تقرير مخاطر مالي فصلي.',impact:'يوازن المسار المقترح بين النمو، الخدمات، واستدامة الدين.',apply:null},distribute:{title:'توزيع الموارد على الأقاليم',desc:'تعتمد معادلة التوزيع على عدد السكان، فجوة الخدمات، ومؤشر الاحتياج التنموي، بدل التوزيع المتساوي فقط.',impact:'الواحة والساحل والحدود مؤهلة لزيادة الاستثمار في الدورة المقبلة.',apply:null},regional:{title:'مبادرة إقليم '+state.selectedRegion,desc:'حزمة تنموية محلية لرفع جودة الخدمات في '+state.selectedRegion+'، تُنسقها الإدارة الإقليمية بالتعاون مع الوزارات القطاعية.',impact:'مؤشر الخدمات +3 · احتياطي النقد −0.3 مليار دولار',apply:()=>{const p=provinces.find(x=>x.name===state.selectedRegion);if(p)p.health=Math.min(100,p.health+3);state.reserves=Math.max(0,state.reserves-.3)}},tax:{title:'مراجعة النظام الضريبي',desc:'يمكن تعديل معدل الضريبة عبر صفحة الاقتصاد والمالية. راعِ أثر التغيير على الأسر، الاستثمار، والإيرادات العامة.',impact:`المعدل الحالي ${state.tax}%. التغييرات الكبيرة قد تبطئ الاستثمار أو تضغط على الدخول المتوسطة.`,apply:null},newProject:{title:'اقتراح مشروع وطني',desc:'تبدأ المشاريع بدراسة جدوى، ثم تقييم الأثر المالي والبيئي، ثم اعتماد مجلس الوزراء. لا يُطلق مشروع قبل توضيح مصدر تمويله.',impact:'الخطوة التالية: تحديد القطاع والإقليم ومؤشرات الأثر.',apply:null},newLaw:{title:'صياغة مقترح سياسة',desc:'كل مقترح يمر بمراجعة الأثر الاقتصادي والاجتماعي، والتشاور مع الجهات المعنية، ثم عرضه على اللجنة المختصة.',impact:'المبدأ: الشفافية والتقييم قبل الاعتماد.',apply:null},policy:{title:'متابعة مسار القرار',desc:'يتضمن ملف السياسة دراسة الأثر المتوقع، ملاحظات الوزارات واللجان، وخطة التنفيذ والقياس.',impact:'يتم تسجيل كل تحديث في السجل الحكومي الموحد.',apply:null}};
function runAction(key){const a=actions[key];if(!a)return;modal(a.title,`${a.desc}<br><br><strong>الأثر المتوقع</strong><br>${a.impact}`,a.apply?'اعتماد القرار':'إغلاق');if(a.apply){const ok=document.querySelector('.modal-ok');ok.addEventListener('click',()=>{a.apply();state.events.unshift({icon:'✓',title:`اعتماد قرار: ${a.title}`,time:'الآن · مكتب الرئيس',status:'معتمد'});save();document.getElementById('modalRoot').innerHTML='';render();showToast('تم اعتماد القرار، وسيظهر أثره في مؤشرات الدولة.')})}}
function advanceMonth(){state.month++;if(state.month>=12){state.month=0;state.year++}const taxEffect=(state.tax-22)*-.018;const investment=(state.infra-12)*.025;const education=(state.education-16)*.008;state.growth=Math.max(-2,Math.min(10,state.growth+.10+investment+education+taxEffect+(Math.random()-.45)*.24));state.gdp*=1+state.growth/1200;state.inflation=Math.max(1,Math.min(20,state.inflation+(state.tax<15?.15:-.04)+(Math.random()-.55)*.32));state.debt=Math.max(15,Math.min(95,state.debt+(state.tax<18?.35:-.10)+(state.infra>17?.12:0)));state.approval=Math.max(20,Math.min(96,Math.round(state.approval+(state.growth>3?1:0)+(state.inflation>6?-1:0)+(Math.random()>.7?1:0))));state.unemployment=Math.max(2,Math.min(25,state.unemployment-.06+(state.growth<2?.1:0)));state.reserves=Math.max(2,state.reserves+(Math.random()-.45)*.5+(state.growth>3?.12:0));state.water=Math.max(25,Math.min(100,state.water+(state.month===7?-5:state.month===1?4:-1)));state.energy=Math.max(40,Math.min(100,state.energy+(Math.random()-.48)*2));let event;if(state.water<55){event={icon:'⌁',title:'تراجع مخزون المياه يتطلب استجابة حكومية',time:'هذا الشهر · وزارة الموارد',status:'أولوية',warn:true};state.approval=Math.max(20,state.approval-1)}else if(state.growth>4.5){event={icon:'↗',title:'تحسن مؤشرات النمو يعزز ثقة المستثمرين',time:'هذا الشهر · وزارة الاقتصاد',status:'إيجابي'}}else{event={icon:'▤',title:'نشر التقرير الشهري لأداء الوزارات',time:'هذا الشهر · مكتب الرئاسة',status:'متابعة'}}state.events.unshift(event);state.events=state.events.slice(0,6);state.history.unshift({month:state.month,year:state.year,gdp:state.gdp,growth:state.growth});state.history=state.history.slice(0,12);save();render();modal(`موجز شهر ${['يناير','فبراير','مارس','أبريل','مايو','يونيو','يوليو','أغسطس','سبتمبر','أكتوبر','نوفمبر','ديسمبر'][state.month]} ${state.year}`,`<strong>الاقتصاد:</strong> النمو ${fmt(state.growth)}%، التضخم ${fmt(state.inflation)}%.<br><strong>المواطنون:</strong> الرضا ${state.approval}%، البطالة ${fmt(state.unemployment)}%.<br><strong>المالية:</strong> الدين العام ${fmt(state.debt)}% من الناتج، الاحتياطي ${fmt(state.reserves)} مليار دولار.<br><br><strong>حدث الشهر:</strong> ${event.title}`,'متابعة')}
document.querySelectorAll('.nav-item').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));document.getElementById('advanceBtn').addEventListener('click',advanceMonth);document.getElementById('notificationBtn').addEventListener('click',()=>{navigate('overview');showToast('لا توجد تنبيهات عاجلة جديدة.')});document.getElementById('cabinetBtn').addEventListener('click',()=>modal('محضر مجلس الوزراء · الجلسة الدورية','<strong>جدول الأعمال</strong><br>١. مراجعة مؤشرات الأداء الاقتصادي والمالي.<br>٢. خطة استقرار المياه في الأقاليم الداخلية.<br>٣. تسريع المشاريع الوطنية المتأخرة.<br>٤. متابعة جودة الخدمات الصحية والتعليمية.','تم الاطلاع'));render();

